<?php

namespace App\Http\Controllers;

use App\Exceptions\TreasuryException;
use App\Models\TreasuryFinancialAccount;
use App\Models\TreasuryRecurringRule;
use App\Services\TreasuryRecurringService;
use App\Services\TreasurySettings;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

/**
 * Treasury Phase 8 — recurring commitment rules (plan §6, §10).
 *
 * A rule repeats on a schedule (monthly rent, quarterly fee,
 * annual licence — or a repeating receipt). Occurrences are
 * generated by the scheduled job; automatic execution is
 * disabled by default and is NOT built in this phase.
 *
 * All rules live in TreasuryRecurringService; this controller
 * only gates permissions, scopes to the company and turns
 * service exceptions into redirects.
 */
class TreasuryRecurringRuleController extends Controller
{
    protected TreasuryRecurringService $service;

    public function __construct(TreasuryRecurringService $service)
    {
        $this->service = $service;
    }

    public function index(Request $request)
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        $creatorId = (int) Auth::user()->creatorId();

        $query = TreasuryRecurringRule::where('created_by', $creatorId)
            ->withCount('occurrences')
            ->orderByDesc('id');

        if ($request->filled('state')) {
            $query->where('state', $request->state);
        }
        if ($request->filled('direction')) {
            $query->where('direction', $request->direction);
        }

        $rules = $query->paginate(25);

        return view('treasury.recurring.rules.index', compact('rules'));
    }

    public function create()
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        $creatorId = (int) Auth::user()->creatorId();
        $accounts = TreasuryFinancialAccount::where('created_by', $creatorId)
            ->where('status', 'active')
            ->with('bankAccount')
            ->orderBy('code')
            ->get();
        $baseCurrency = TreasurySettings::baseCurrency($creatorId);

        return view('treasury.recurring.rules.form', compact('accounts', 'baseCurrency'));
    }

    public function store(Request $request)
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        $creatorId = (int) Auth::user()->creatorId();

        try {
            $rule = $this->service->createRule($creatorId, $request->all(), (int) Auth::id());
        } catch (TreasuryException $e) {
            return redirect()->back()->withInput()->with('error', $e->getMessage());
        }

        return redirect()->route('treasury-recurring-rules.show', $rule->id)
            ->with('success', __('Recurring rule created. Occurrences are generated by the daily job.'));
    }

    public function show(int $id)
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        $creatorId = (int) Auth::user()->creatorId();

        try {
            $rule = $this->service->ruleForCompany($creatorId, $id);
        } catch (TreasuryException $e) {
            return redirect()->route('treasury-recurring-rules.index')->with('error', $e->getMessage());
        }

        $occurrences = $rule->occurrences()->orderBy('scheduled_date')->orderBy('id')->paginate(25);

        return view('treasury.recurring.rules.show', compact('rule', 'occurrences'));
    }

    public function edit(int $id)
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        $creatorId = (int) Auth::user()->creatorId();

        try {
            $rule = $this->service->ruleForCompany($creatorId, $id);
        } catch (TreasuryException $e) {
            return redirect()->route('treasury-recurring-rules.index')->with('error', $e->getMessage());
        }

        $accounts = TreasuryFinancialAccount::where('created_by', $creatorId)
            ->where('status', 'active')
            ->with('bankAccount')
            ->orderBy('code')
            ->get();
        $baseCurrency = TreasurySettings::baseCurrency($creatorId);

        return view('treasury.recurring.rules.form', compact('rule', 'accounts', 'baseCurrency'));
    }

    public function update(Request $request, int $id)
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        $creatorId = (int) Auth::user()->creatorId();

        try {
            $rule = $this->service->updateRule($creatorId, $id, $request->all());
        } catch (TreasuryException $e) {
            return redirect()->back()->withInput()->with('error', $e->getMessage());
        }

        return redirect()->route('treasury-recurring-rules.show', $rule->id)
            ->with('success', __('Rule updated. Future unconfirmed occurrences were regenerated.'));
    }

    public function pause(int $id)
    {
        return $this->changeState($id, 'pauseRule', __('Rule paused. Earlier occurrences are kept.'));
    }

    public function resume(int $id)
    {
        return $this->changeState($id, 'resumeRule', __('Rule resumed.'));
    }

    public function end(int $id)
    {
        return $this->changeState($id, 'endRule', __('Rule ended. Earlier occurrences are kept.'));
    }

    protected function changeState(int $id, string $method, string $success)
    {
        if (! Auth::user()->can('manage treasury recurring')) {
            return redirect()->back()->with('error', __('Permission denied.'));
        }

        try {
            $rule = $this->service->{$method}((int) Auth::user()->creatorId(), $id);
        } catch (TreasuryException $e) {
            return redirect()->back()->with('error', $e->getMessage());
        }

        return redirect()->route('treasury-recurring-rules.show', $rule->id)->with('success', $success);
    }
}
